# Write cudacpp_spec.txt, listing the cudacpp processes needed by this MG5aMC NLO
# process directory, one line per cudacpp library: "<tag> <ccproc> '<generate command>'"
#   born  epem_bbx  'generate e+ e- > b b~'
#   real1 epem_bbxg 'generate e+ e- > b b~ g'
# The information is read from the Fortran code generated by MG5aMC (it works on a
# raw directory, before any vfalt patches): the Born process from born.f, and each
# real-emission process from matrix_<N>.f. The tag real<N> is the N of matrix_<N>.f,
# i.e. the N of the SMATRIX<N> that real_me_chooser.f calls for a given nFKSprocess.
# The particle order is the one of the Fortran code (the cudacpp momenta must match).
# Only the first 'Process:' line of each file is used: several processes in the same
# matrix_<N>.f (e.g. d d~ and s s~) share the same matrix element.
# The coupling orders on the 'Process:' lines refer to the full NLO process and are
# not copied to the generate commands (they are kept as comments in the output).

set -e
set -o pipefail

cd $(dirname $0)/..
if [ "$1" != "" ]; then
  echo "Usage: $0"
  exit 1
fi

pdirs=$(ls -d SubProcesses/P*_*/ 2>/dev/null || true)
if [ "${pdirs}" == "" ]; then
  echo "ERROR! No SubProcesses/P*_* directory found in $(pwd)"
  exit 1
elif [ $(echo ${pdirs} | wc -w) -ne 1 ]; then
  echo "ERROR! Several SubProcesses/P*_* directories found (not supported yet): ${pdirs}"
  exit 1
fi
pdir=${pdirs%/}

# Print the first 'Process:' line of a Fortran file (without the leading 'C     Process: ')
function processLine() {
  local line=$(grep -m1 -i '^C *Process:' $1 || true)
  if [ "${line}" == "" ]; then echo "ERROR! No 'Process:' line in $1" > /dev/stderr; exit 1; fi
  echo "${line}" | sed 's/^C *Process: *//I'
}

# Keep only the particles from a 'Process:' line (drop '[...]', coupling orders and '@N')
function particles() {
  echo "$1" | sed -e 's/\[.*$//' -e 's/@.*$//' | awk '{for(i=1;i<=NF;i++) if($i!~/[=^]/) printf("%s%s",(n++?" ":""),$i); print ""}'
}

# Build the cudacpp process name from the particles (e.g. 'e+ e- > b b~ g' -> 'epem_bbxg')
function ccName() {
  echo "$1" | sed -e 's/ //g' -e 's/>/_/' -e 's/+/p/g' -e 's/-/m/g' -e 's/~/x/g'
}

out=vfold/cudacpp_spec.txt
tmp=${out}.tmp
\rm -f ${tmp}
echo "# Generated by $(basename $0) from ${pdir} - DO NOT EDIT" >> ${tmp}
echo "# <tag> <cudacpp process> '<generate command>'" >> ${tmp}
procline=$(processLine ${pdir}/born.f)
parts=$(particles "${procline}")
echo "# born.f: ${procline}" >> ${tmp}
echo "born $(ccName "${parts}") 'generate ${parts}'" >> ${tmp}
nreal=0
for f in $(cd ${pdir}; ls matrix_*.f | sort -V); do
  n=${f#matrix_}; n=${n%.f}
  if ! [[ "${n}" =~ ^[0-9]+$ ]]; then continue; fi
  nreal=$((nreal+1))
  if [ "${n}" != "${nreal}" ]; then echo "ERROR! Unexpected matrix files in ${pdir} (found ${f}, expected matrix_${nreal}.f)"; exit 1; fi
  procline=$(processLine ${pdir}/${f})
  parts=$(particles "${procline}")
  echo "# ${f}: ${procline}" >> ${tmp}
  echo "real${n} $(ccName "${parts}") 'generate ${parts}'" >> ${tmp}
done
if [ "${nreal}" == "0" ]; then echo "ERROR! No matrix_<N>.f files in ${pdir}"; exit 1; fi
\mv -f ${tmp} ${out}
echo "Created $(pwd)/${out}"
cat ${out}
